<h1>Pengguna</h1><section class="card"><h2>Tambah Pengguna</h2><form method="post"><?php token(); ?><div class="formgrid"><label>Username<input name="username" pattern="[A-Za-z0-9_.-]{3,80}" maxlength="80" required autocomplete="off"></label><label>Password awal<input name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><label>Peran<select name="role"><?php foreach(['peserta','aset','bendahara','pimpinan','admin'] as $role): ?><option><?=esc($role)?></option><?php endforeach; ?></select></label></div><p class="muted">Peran peserta adalah petugas data peserta. Pimpinan hanya membaca data. Admin mengakses seluruh modul.</p><button name="action" value="add_user">Buat Pengguna</button></form></section><section class="card"><h2>Daftar Pengguna</h2><div class="tablewrap"><table><thead><tr><th>Username</th><th>Peran</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody><?php foreach(sql('SELECT id,username,role,created_at FROM users ORDER BY username') as $r): ?><tr><td><?=esc($r['username'])?></td><td><?=esc($r['role'])?></td><td><?=esc($r['created_at'])?></td><td><details class="ganti"><summary class="btnlink">Ganti password</summary><form method="post"><?php token(); ?><input type="hidden" name="id" value="<?=esc($r['id'])?>"><label>Password baru (12–72 karakter)<input type="password" name="password_baru" minlength="12" maxlength="72" autocomplete="new-password" required></label><label>Ulangi password baru<input type="password" name="konfirmasi" minlength="12" maxlength="72" autocomplete="new-password" required></label><button class="mini" name="action" value="reset_password" onclick="return confirm('Ganti password <?=esc($r['username'])?>?')">Simpan</button></form></details></td></tr><?php endforeach; ?></tbody></table></div></section>